from langsmith import Client

client = Client()

def target(inputs):
    return {"output": inputs["text"].upper()}

def evaluator(run, example):
    score = run.outputs["output"] == example.outputs["expected"]
    return {"key": "correct", "score": score}

results = client.evaluate(
    target,
    data="my_dataset",
    evaluators=[evaluator],
    experiment_prefix="uppercase-test",
    max_concurrency=4,
)

