from langsmith import evaluate


def target(inputs):
    return {"answer": inputs["text"].upper()}


def evaluator(inputs, outputs):
    return {"key": "is_upper", "score": outputs["answer"].isupper()}

results = evaluate(
    target,
    data=[{"text": "hello"}],
    evaluators=[evaluator],
)
print(results)

from langchain_classic.evaluation.schema import StringEvaluator

class LengthEvaluator(StringEvaluator):
    evaluation_name = "length"
    requires_reference = False

    def _evaluate_strings(self, prediction, reference=None, input=None, **kwargs):
        return {"score": len(prediction) < 100}

evaluator = LengthEvaluator()
result = evaluator.evaluate_strings(
    prediction="A short answer.",
    input="Give a short answer."
)
print(result)

